// UserPromptSubmit: "good morning/afternoon/evening claude" ALWAYS starts the check-in.
// The skill's description lets Claude pick it on its own; this hook makes the greeting deterministic.
import { readInput } from "./rules.mjs";

const { prompt = "" } = await readInput();
const m = /^\s*good\s+(morning|afternoon|evening)[\s,]+claude[\s!.]*$/i.exec(prompt);
if (m) {
  const part = m[1].toLowerCase();
  process.stdout.write(JSON.stringify({
    hookSpecificOutput: {
      hookEventName: "UserPromptSubmit",
      additionalContext: `The user greeted you with "good ${part}". Invoke the check-in skill now (Skill tool, skill "check-in") in ${part} mode.`,
    },
  }));
}

// The harness's hard rules, enforced by hooks. Claude cannot edit this folder (deny rules).

// Rule 1: never change the user's source data in data/ (calendar export, coursework, budgets, prefs).
//   A command is blocked if it mentions data/ AND does anything that can write.
export const DATA_PATH = /(^|[\s"'=/(])(\.\/)?data\//;
export const WRITE_VERB = /(^|[^<])>{1,2}|\btee\b|\brm\b|\bmv\b|\bcp\b|\bsed\s+-i|\bperl\s+-[a-z]*i|\btouch\b|\btruncate\b|\bchmod\b|\bchown\b|\bln\b|\bunlink\b|\bdd\b|\bgit\s+(checkout|restore|rm|mv|reset|stash|clean)\b|writeFile|\.write\(|open\([^)]*['"][wa]/;

// Rule 2: never write to the user's personal calendar (Apple Calendar, Google Calendar).
//   Opening a .ics file on macOS imports it into Calendar, so that's blocked too.
export const CALENDAR = /Library\/Calendars|\bicalbuddy\b|open\s+(-a\s+)?["']?(Calendar|iCal)\b|\bopen\b[^|;&]*\.ics\b|webcal:|x-apple-calevent|calendar\.google\.com|googleapis\.com\/calendar/i;

// Rule 3: never read text-message content (Messages / Contacts databases).
export const MESSAGES_DB = /Library\/Messages|chat\.db|\bsqlite3?\b|AddressBook|\.abcddb\b/i;

// Rule 4: never send a text (or any message) to anyone. osascript also covers scripting Calendar.
export const SENDING = /\bosascript\b|Messages\.app|open\s+(-a\s+)?["']?Messages\b|\bshortcuts\s+run\b|\b(sms|imessage|facetime|tel|mailto):/i;

// Rule 5: never purchase anything. The gift scout researches and links product pages only.
//   Blocks checkout/cart/payment URLs and "buy now"/"place order" automation.
export const PURCHASE = /\/(checkout|cart|basket|purchase|payment|pay|order)s?(\/|\?|#|\b)|add[-_ ]?to[-_ ]?(cart|bag|basket)|buy[-_ ]?now|place[-_ ]?order|paypal\.com|pay\.google\.com|checkout\.stripe\.com|\/gp\/(buy|cart)/i;

export async function readInput() {
  let raw = "";
  for await (const chunk of process.stdin) raw += chunk;
  return JSON.parse(raw || "{}");
}

export function block(reason) {
  process.stderr.write(`BLOCKED by harness rule: ${reason}\nDo not try another way. Tell the user what was blocked and suggest the change for them to make.\n`);
  process.exit(2);
}

// PreToolUse(Bash): deny rules can't see inside shell commands, so this hook does.
import { CALENDAR, DATA_PATH, MESSAGES_DB, PURCHASE, SENDING, WRITE_VERB, block, readInput } from "./rules.mjs";

const { tool_input = {} } = await readInput();
const cmd = String(tool_input.command ?? "");
if (DATA_PATH.test(cmd) && WRITE_VERB.test(cmd)) block("data/ is the user's source data. Claude may read it, never change it.");
if (CALENDAR.test(cmd)) block("the harness never writes to the user's personal calendar. Put the plan in days/ instead.");
if (MESSAGES_DB.test(cmd)) block("the Messages/Contacts databases are off-limits. The harness never reads text messages.");
if (PURCHASE.test(cmd)) block("the harness never purchases anything. Suggest the product link; the user buys it.");
if (SENDING.test(cmd)) block("the harness never sends texts or messages to anyone.");

