// PreToolUse(Write|Edit|MultiEdit|NotebookEdit): backs up the deny rules on data/, and stops
// Claude from writing NEW code that would sidestep guard-bash.
import { CALENDAR, MESSAGES_DB, PURCHASE, SENDING, block, readInput } from "./rules.mjs";

const { tool_input = {}, cwd = process.cwd() } = await readInput();
const path = String(tool_input.file_path ?? tool_input.notebook_path ?? "");
const root = process.env.CLAUDE_PROJECT_DIR || cwd;
const rel = path.startsWith(root) ? path.slice(root.length).replace(/^\/+/, "") : path;
if (/^(\.\/)?data\//.test(rel)) block(`data/ is the user's source data (${rel}). Claude may read it, never change it.`);
if (/Library\/Calendars/.test(path)) block("the harness never writes to the user's personal calendar.");
if (/\.md$/i.test(path)) process.exit(0); // prose may mention the rules
const text = [tool_input.content, tool_input.new_string, tool_input.new_source,
  ...(tool_input.edits ?? []).map((e) => e.new_string)].filter(Boolean).join("\n");
if (MESSAGES_DB.test(text)) block(`writing code that touches the Messages/Contacts databases (${rel}).`);
if (SENDING.test(text)) block(`writing code that could send a message (${rel}).`);
if (PURCHASE.test(text)) block(`checkout/cart/payment links or buying automation (${rel}). Link product pages only.`);
if (CALENDAR.test(text)) block(`writing code that could write to the personal calendar (${rel}).`);

